<div class="modal fade" id="departmentStateModal" tabindex="-1" aria-labelledby="departmentStateTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><form method="POST" action="<?= APP_URL ?>/admin-departements" class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="departmentStateTitle">Changer le statut</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fermer"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?= genererTokenCSRF() ?>"><input type="hidden" name="action" value="etat"><input type="hidden" name="id" id="stateDepartmentId"><input type="hidden" name="actif" id="stateDepartmentActive"><p class="fw-semibold" id="stateDepartmentName"></p><p class="text-muted small mb-0" id="stateDepartmentNotice"></p></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Retour</button><button class="btn btn-primary" type="submit">Confirmer</button></div></form></div></div>
<script>
(function(){
    const search=document.getElementById('departmentSearch'),status=document.getElementById('departmentStatus');
    function filter(){let count=0;const term=search.value.trim().toLocaleLowerCase('fr');document.querySelectorAll('[data-department-row]').forEach(row=>{row.hidden=!row.cells[0].textContent.toLocaleLowerCase('fr').includes(term)||(status.value!==''&&row.dataset.active!==status.value);if(!row.hidden)count++;});document.getElementById('departmentEmpty').hidden=count>0;}
    search.addEventListener('input',filter);status.addEventListener('change',filter);
    document.getElementById('departmentStateModal').addEventListener('show.bs.modal',event=>{const button=event.relatedTarget,active=button.dataset.active==='1';document.getElementById('stateDepartmentId').value=button.dataset.id;document.getElementById('stateDepartmentActive').value=button.dataset.active;document.getElementById('stateDepartmentName').textContent=button.dataset.name;document.getElementById('departmentStateTitle').textContent=active?'Réactiver le département':'Désactiver le département';document.getElementById('stateDepartmentNotice').textContent=active?'Le département sera à nouveau disponible dans les listes.':'Le département ne pourra plus être sélectionné pour une nouvelle demande ou une nouvelle affectation. Son historique reste disponible.';});
})();
</script>
